const expertClassificationMap={actual:'actual_finding',context:'context_dependent',disclaimer:'limitation_or_disclaimer',history:'repair_history_or_evidence',wear:'context_dependent',split:'actual_finding'};
const expertSeverityLabels={safety:'דגש בטיחותי',high:'משמעות גבוהה',medium:'משמעות בינונית',low:'משמעות נמוכה',none:'ללא משקל עצמאי'};
const expertDecisionByFormulaId=new Map();
const expertDecisionByAliasId=new Map();
const expertDecisionByPhrase=new Map();
expertCalibrationDecisions.forEach(decision=>{
  (decision.formulaIds||[]).forEach(id=>expertDecisionByFormulaId.set(id,decision));
  (decision.aliasIds||[]).forEach(id=>expertDecisionByAliasId.set(id,decision));
  (decision.phrases||[]).forEach(phrase=>expertDecisionByPhrase.set(normalizeFindingText(phrase),decision));
});

function expertDecisionForFormula(formula){
  const rawId=String(formula?.id||'').replace(/^alias-/,'');
  const byId=expertDecisionByFormulaId.get(rawId)||expertDecisionByAliasId.get(rawId);
  if(byId) return byId;
  const candidates=[formula?.text,...(formula?.terms||[])].filter(Boolean).map(normalizeFindingText);
  for(const text of candidates){
    if(expertDecisionByPhrase.has(text)) return expertDecisionByPhrase.get(text);
  }
  return null;
}

function expertSeverityFor(decision,formula){
  const text=normalizeFindingText(formula?.text||'');
  if(decision.id==='control_arm_bushings') return 'low';
  if((decision.id==='body_paint_repairs'||decision.id==='frame_cosmetic') && /מצב ירוד/.test(text)) return 'high';
  if(decision.classification!=='split') return decision.severity;
  return /הלחמ|חיבורים לא מקוריים לרוחב/.test(text)?'high':decision.severity;
}

function expertConclusion(decision,severity){
  if(decision.id==='engine_warranty') return 'ללא ממצא תומך, הנוסח „אין אחריות על המנוע” הוא הסתייגות כללית ואינו מקבל משקל עצמאי.';
  if(decision.id==='control_arm_bushings') return 'נרשם ממצא בתותבים או במשולשים במתלה הקדמי. יש לבדוק את חומרתו ואת הטיפול הנדרש במוסך.';
  if((decision.id==='body_paint_repairs'||decision.id==='frame_cosmetic') && severity==='high') return 'ניסוח מפורש של מצב פחחות וצבע ירוד הוא ממצא בעל משמעות גבוהה, ויש לברר את היקף התיקונים אצל בעל מקצוע מתאים.';
  let base='';
  if(decision.classification==='disclaimer') base='זהו ניסוח של הסתייגות כללית או מגבלת בדיקה. הוא אינו קובע לבדו שקיימת תקלה ברכב ואינו מביע עמדה על עבודת המכון.';
  else if(decision.classification==='history') base='זהו מידע על תיקון, פירוק או החלפה קודמים; אין להסיק ממנו לבדו שקיימת תקלה פעילה.';
  else if(decision.classification==='context') base=severity==='high'?'זוהי אזהרה משמעותית, אך יש לפרש אותה לפי הנוסח והממצאים הנלווים בדוח.':'המשמעות תלויה בנוסח המדויק ובממצאים הנלווים, ואין להחמיר או להקל מעבר למה שנכתב.';
  else if(decision.classification==='wear') base='זהו ממצא של בלאי; יש להביא אותו בחשבון לפי חומרתו בלי להציגו אוטומטית ככשל חמור.';
  else if(severity==='safety') base='זהו ליקוי ממשי בעל השלכה בטיחותית שדורש טיפול או בירור מקצועי.';
  else if(severity==='high') base='זהו ממצא בעל משמעות גבוהה שדורש בירור מקצועי והשלמת בדיקות לפי הצורך.';
  else if(severity==='medium') base='זהו ממצא בעל משמעות בינונית; יש לברר את חומרתו ואת הטיפול הנדרש.';
  else if(severity==='low') base='זהו ממצא בעל משמעות נמוכה; יש לבדוק את מצב החלק ואת הטיפול הנדרש.';
  else base='לממצא אין משקל עצמאי ללא ממצא נוסף שמחזק אותו.';
  const note=severity==='low'&&/גבוה/.test(decision.note||'')?'':decision.note;
  return note?base+' '+note:base;
}

function applyExpertCalibration(rule,formula){
  const decision=expertDecisionForFormula(formula);
  if(!decision) return rule;
  const severity=expertSeverityFor(decision,formula);
  const classification=expertClassificationMap[decision.classification]||'context_dependent';
  const sourceText=formula?.text||rule.sourceText||rule.matchedTerm||'';
  const calibrated={
    ...rule,
    id:'expert-'+decision.id,
    category:decision.category||rule.category,
    tag:expertSeverityLabels[severity]||rule.tag,
    tone:severity==='safety'||severity==='high'?'safety':'clarify',
    classification,
    reportSeverity:severity==='none'?null:severity,
    contextPolicy:decision.agePolicy,
    meaning:'הנוסח שייך לקבוצה המקצועית „'+decision.title+'”.',
    question:'',
    decision:expertConclusion(decision,severity),
    sourceText,
    expertDecision:decision
  };
  if(decision.id==='oil_burning'&&/לבדוק (?:תצרוכת|צריכת) שמן/.test(normalizeFindingText(sourceText))){
    calibrated.tag='הסתייגות כללית';
    calibrated.tone='clarify';
    calibrated.classification='limitation_or_disclaimer';
    calibrated.reportSeverity=null;
    calibrated.meaning='הנוסח ממליץ לבדוק תצרוכת שמן בנסיעה. הוא אינו קובע לבדו שהמנוע שורף שמן.';
    calibrated.decision='אין לספור את המשפט כליקוי עצמאי. יש לייחס משקל רק לממצא ממשי נוסף, אם נרשם לצד ההמלצה.';
  }
  if(decision.id==='gearbox_mount'){
    calibrated.tag='ליקוי נקודתי';
    calibrated.tone='clarify';
    calibrated.reportSeverity='low';
    calibrated.meaning='נרשמה תושבת פגומה של תיבת ההילוכים. התושבת מחברת את התיבה למרכב ומבודדת תנועה ורעידות; הממצא אינו קובע שתיבת ההילוכים עצמה פגומה.';
    calibrated.decision='יש לבדוק את התושבת במוסך ולטפל בה לפי הצורך. אין לסווג את תיבת ההילוכים כלא תקינה על סמך ממצא זה בלבד.';
  }
  const specific=specificFindingInterpretation(calibrated);
  if(specific){
    calibrated.meaning=specific.meaning;
    calibrated.decision=specific.decision;
  }
  return calibrated;
}

function reportKmForEngineWarranty(text){
  const reportValues=[];
  const known=Number(loadedKm||externalVehicleData.kmHistory?.[0]?.km||0);
  const raw=normalizeFindingText(text);
  const number='([0-9]{4,7}|[0-9]{1,3}(?:\\s+[0-9]{3}){1,2})';
  const unit='(?:קמ|קילומטראז|קילומטרים?)';
  const patterns=[
    new RegExp('קמ\\s*(?:או\\s*מייל)?\\s*'+number,'gi'),
    new RegExp('(?:מונה\\s+)?'+unit+'\\s*(?:מונה\\s*)?'+number,'gi'),
    new RegExp(number+'\\s*(?:מונה\\s*)?'+unit,'gi'),
    new RegExp('מונה\\s+'+number,'gi')
  ];
  patterns.forEach(pattern=>{
    for(const match of raw.matchAll(pattern)){
      const value=Number(String(match[1]).replace(/[^0-9]/g,''));
      if(value>=1000&&value<=2000000) reportValues.push(value);
    }
  });
  if(reportValues.length) return Math.max(...reportValues);
  return known>=1000&&known<=2000000?known:0;
}

function applyEngineWarrantyContext(result,text){
  const warranty=result.findings.find(item=>item.id==='expert-engine_warranty');
  if(!warranty) return result;
  const normalized=normalizeFindingText(text);
  const reasons=[];
  const km=reportKmForEngineWarranty(text);
  if(km>=200000) reasons.push('קילומטראז׳ של 200,000 ק״מ ומעלה');
  const triggerIds=new Set(['expert-engine_vapor_blowby','expert-internal_knocks','expert-compression_leakdown']);
  if(result.findings.some(item=>triggerIds.has(item.id))) reasons.push('נקישות במנוע, דליפות לחץ או לחץ עוקה');
  if(/נזיל(?:ה|ות) (?:שמן )?(?:חזק|חזקות|חריפ|חריפות|רבות)/.test(normalized)) reasons.push('נזילות חזקות');
  if(/פילטר (?:אוויר )?פתוח|אגזוז לחץ|מערכת פליטה (?:שונתה|שונה|לא מקורית)|שיפור(?:ים|י)? מנוע|מנוע משופר|שינוי(?:ים)? במנוע|תוכנת מנוע|ציפ מנוע|סטייג|stage/.test(normalized)) reasons.push('שיפורי מנוע');
  if(!reasons.length){
    warranty.tag='הסתייגות כללית';
    warranty.tone='clarify';
    warranty.reportSeverity=null;
    warranty.meaning='הנוסח „אין אחריות על המנוע” הופיע ללא ממצא שמסביר את ההסתייגות.';
    warranty.decision='הנוסח לבדו אינו מצביע על ליקוי במנוע ואינו מקבל משקל עצמאי.';
    return result;
  }
  const uniqueReasons=[...new Set(reasons)];
  warranty.tag='אזהרה משמעותית';
  warranty.tone='safety';
  warranty.reportSeverity='high';
  warranty.meaning='הנוסח „אין אחריות על המנוע” מופיע לצד '+uniqueReasons.join(', ')+'.';
  warranty.decision='בצירוף הנתונים האלה ההסתייגות מקבלת משמעות גבוהה יותר. יש לבחון אותה יחד עם ממצאי המנוע ולבצע בירור מקצועי; אין להסיק סיבה אחרת שלא מופיעה בבדיקה.';
  return result;
}

function applyReportMileageContext(result,text){
  const km=reportKmForEngineWarranty(text);
  result.reportKm=km||0;
  if(!km) return result;
  const wearIds=new Set([
    'expert-internal_wear','expert-engine_vapor_blowby','expert-internal_knocks',
    'expert-compression_leakdown','expert-oil_burning','expert-engine_output'
  ]);
  result.findings=result.findings.map(item=>{
    const source=normalizeFindingText(item.sourceText||item.matchedTerm||item.meaning||'');
    const explicitWear=wearIds.has(item.id)||/בלאי פנימי|לחץ עוקה|נקיש|דליפות לחץ|לחץ דחיסה|מנוע שורף שמן|שריפת שמן|הספק מנוע ירוד|סחיבה חלשה/.test(source);
    if(!explicitWear||item.classification==='limitation_or_disclaimer'||item.classification==='recommendation') return item;
    const mileageText=`בדוח נקרא קילומטראז׳ של ${fmtNum(km)} ק״מ. `+(km>=200000
      ? 'זהו קילומטראז׳ גבוה שנותן הקשר לבלאי שנרשם ומחזק את הצורך בבירור ממוקד של מצב המנוע. הוא אינו מבטל את הממצא ואינו מוכיח לבדו צורך בשיפוץ.'
      : 'הקילומטראז׳ משמש הקשר לבלאי שנרשם, אך אינו משנה לבדו את האבחנה ואינו מוכיח צורך בשיפוץ.');
    const existing=String(item.contextNote||'').trim();
    return {...item,reportKm:km,contextNote:existing?existing+' '+mileageText:mileageText};
  });
  return result;
}

function loadCustomFormulas(){return []}
function loadFormulaOverrides(){return []}
function formulaOverrideKey(category,text){return normalizeFindingText(category)+'|'+normalizeFindingText(text)}
function formulaOverrideFor(){return null}
function applyManagerFormulaOverride(item){return item}

const reportSeverityLabels={safety:'דגש בטיחותי',high:'משמעות גבוהה',medium:'משמעות בינונית',low:'משמעות נמוכה',minor:'משמעות נמוכה',none:'ללא משקל עצמאי'};

function isOperationalFormula(item){
  return Boolean(item)&&item.active!==false&&item.category!=='הערות כלליות';
}

function classificationTemplate(type,category,text){
  const label=formulaClassificationLabels[type]||formulaClassificationLabels.context_dependent;
  const templates={
    actual_finding:`„${text}” הוא ממצא מסוים שנרשם בסעיף ${category}. ההסבר משקף את נוסח הדוח ואינו חוות דעת על מכון הבדיקה.`,
    limitation_or_disclaimer:`„${text}” הוא ניסוח של הסתייגות כללית או מגבלת בדיקה. הוא אינו הוכחה לתקלה ברכב ואינו מייחס למכון כוונה כלשהי.`,
    recommendation:`„${text}” הוא ניסוח של המלצה או בדיקת המשך. אין לספור אותו כליקוי שנמצא בפועל.`,
    maintenance_recommendation:`„${text}” מתאר צורך בתחזוקה או בכיוון, ולא בהכרח תקלה ברכיב.`,
    repair_history_or_evidence:`„${text}” מציין סימן לפירוק, תיקון, החלפה או עבודה קודמת. יש לפרש אותו לפי החלק ולפי קבוצת המשמעות שבה הוא מופיע בדוח; הוא אינו מוכיח לבדו תקלה פעילה.`,
    information:`„${text}” הוא מידע תיאורי בלבד ואינו ליקוי בפני עצמו.`,
    context_dependent:`„${text}” עשוי להיות ליקוי ממשי או בלאי סביר. משקלו נקבע לפי גיל הרכב, הקילומטראז׳ והממצאים הנלווים.`
  };
  return {label,meaning:templates[type]||templates.context_dependent,question:''};
}

function professionalDecision(item){
  if(item.decision) return item.decision;
  if(item.reportSeverity==='high') return 'זהו ממצא בעל משמעות גבוהה. יש לברר את היקפו ולהשלים בדיקה מקצועית מתאימה.';
  if(item.reportSeverity==='medium') return 'זהו ממצא בעל משמעות בינונית. יש לברר את חומרתו ואת הטיפול הנדרש.';
  if(item.reportSeverity==='low') return 'זהו ממצא בעל משמעות נמוכה. יש לבדוק את מצב החלק ואת הטיפול הנדרש.';
  if(item.reportSeverity==='minor') return 'זהו ממצא נקודתי או קוסמטי בעל משמעות נמוכה, כל עוד לא נרשם ממצא מהותי נוסף באותה מערכת.';
  if(item.classification==='limitation_or_disclaimer') return 'זהו ניסוח של מגבלת בדיקה או הסתייגות כללית. הוא אינו קובע לבדו שקיימת תקלה ואינו מביע עמדה על עבודת המכון.';
  if(item.classification==='recommendation') return 'הנוסח מציין בדיקת המשך מומלצת ואינו קובע שנמצאה תקלה.';
  if(item.classification==='maintenance_recommendation') return 'הנוסח מצביע על צורך בתחזוקה או בכיוון. יש לברר את הפעולה הנדרשת אצל בעל מקצוע מתאים.';
  if(item.classification==='repair_history_or_evidence') return 'הנוסח מתאר סימן לפירוק, תיקון או החלפה קודמים. יש לפרש אותו לפי החלק ולפי קבוצת המשמעות שבה הוא מופיע בדוח, בלי להסיק השפעה שלא נכתבה.';
  if(item.classification==='information') return 'אין למידע הזה משקל של ליקוי בפני עצמו.';
  if(item.classification==='context_dependent') return item.contextNote||'זהו ממצא תלוי הקשר. יש לפרש אותו לפי גיל הרכב, הקילומטראז׳ והממצאים הנלווים, בלי להסיק מעבר לנוסח הדוח.';
  const safetyCategories=['מערכת הבלמים (ללא פירוק גלגלים)','מערכת ההיגוי','מערכת מתלה קדמי','מערכת מתלה אחורי','צמיגים וחישוקים','שלדת מרכב','שלדה נפרדת'];
  if(safetyCategories.includes(item.category)||/בלמ|היגוי|מתלה|צמיג/.test(item.category||'')) return 'נרשם ממצא במערכת שעשויה להשפיע על בטיחות או יציבות. יש לבצע בירור מקצועי ולטפל בהתאם לממצא המאומת.';
  if(/מנוע|הילוכים|הנעה|גידוש|קירור/.test(item.category||'')) return 'נרשם ממצא מכני שדורש בירור ממוקד במוסך ואימות של מקורו וחומרתו.';
  if(/תאורה/.test(item.category||'')) return 'זהו ליקוי תפקודי שנדרש לתקן. בדרך כלל הוא נקודתי, אלא אם הוא חלק מתקלה חשמלית רחבה יותר.';
  return 'נרשם ממצא שדורש בדיקה והבהרה אצל בעל המקצוע המתאים.';
}

function contextNoteFor(item){
  if(item.expertDecision){
    if(item.contextPolicy==='economic_only') return 'גיל הרכב והקילומטראז׳ נותנים הקשר לממצא, אך אינם מבטלים את עצם קיומו בדוח.';
    if(item.contextPolicy==='expected_wear'&&item.classification!=='limitation_or_disclaimer') return 'ייתכן שמדובר בבלאי צפוי, אך הסיווג המקצועי וחומרת הממצא נשארים כפי שנקבעו.';
    return '';
  }
  if(item.contextPolicy!=='vehicle_age_and_mileage'&&item.classification!=='context_dependent') return '';
  const year=Number(String(document.getElementById('vYear')?.textContent||'').match(/\d{4}/)?.[0]||0);
  const km=Number(loadedKm||externalVehicleData.kmHistory?.[0]?.km||0);
  const age=year?Math.max(0,new Date().getFullYear()-year):null;
  if(age===null&&!km) return 'ללא גיל וקילומטראז׳ אי אפשר לכייל את חומרת הבלאי, ולכן משקלו נשאר בינוני.';
  const young=age!==null&&age<=5,lowKm=Boolean(km&&km<=80000),old=age!==null&&age>=10,highKm=Boolean(km&&km>=150000);
  if(young||lowKm){
    const profile=young&&lowKm?'ברכב צעיר ובעל קילומטראז׳ נמוך':young?'ברכב צעיר':'ברכב בעל קילומטראז׳ נמוך';
    return `${profile}, ממצא כזה פחות צפוי ולכן הוא מחייב בירור מקצועי ממוקד.`;
  }
  if(old||highKm){
    const profile=old&&highKm?'ברכב ותיק ובעל קילומטראז׳ גבוה':old?'ברכב ותיק':'ברכב בעל קילומטראז׳ גבוה';
    return `${profile} ייתכן שמדובר בבלאי רגיל; משקלו נמוך עד בינוני כל עוד אין ממצא חמור נוסף באותה מערכת.`;
  }
  return 'בגיל ובקילומטראז׳ האלה משקל הממצא בינוני; ממצאים נוספים באותה מערכת יכולים להעלות אותו.';
}

const customerRestrictedWording=/(?:עלות|מחיר|שווי|סחירות|ירידת\s*ערך|הוצאה|כלכל|כספי|כדאי|כדאיות|לקנות|קניית|אי[־-]?קנייה|פסיל|לברוח|כיסוי\s*תחת|משפט\s*כיסוי|מקצועיות\s*המכון|המכון\s*(?:טעה|התרשל|הטעה|לא\s*מקצועי))/i;

function neutralCustomerDirection(item){
  if(item?.classification==='limitation_or_disclaimer') return 'זהו ניסוח של הסתייגות כללית או מגבלת בדיקה. הוא אינו קובע לבדו שקיימת תקלה ואינו מביע עמדה על עבודת המכון.';
  if(item?.classification==='recommendation') return 'הנוסח מציין צורך בבדיקת המשך ואינו קובע שנמצאה תקלה.';
  if(item?.classification==='maintenance_recommendation') return 'הנוסח מצביע על צורך בתחזוקה או בכיוון. יש לברר את הפעולה הנדרשת אצל בעל מקצוע מתאים.';
  if(item?.classification==='repair_history_or_evidence') return 'הנוסח מתאר סימן לפירוק, תיקון או החלפה קודמים. יש לבדוק את החלק ואת משמעות הממצא בלי להסיק מעבר למה שנכתב.';
  if(item?.classification==='information') return 'זהו מידע תיאורי בלבד ואינו קובע שקיימת תקלה.';
  if(item?.code||item?.computerDescription) return 'קוד התקלה מספק כיוון לאבחון בלבד. יש לבדוק את מצב הקוד, את הנתונים הנלווים ואת המערכת המתאימה באמצעות ציוד אבחון מקצועי.';
  if(item?.reportSeverity==='safety') return 'נרשם ממצא בעל היבט בטיחותי. יש לבצע בדיקה מקצועית ולטפל בהתאם לממצא המאומת.';
  if(item?.reportSeverity==='high') return 'זהו ממצא בעל משמעות גבוהה. יש לברר את היקפו ולהשלים בדיקה מקצועית מתאימה.';
  if(item?.reportSeverity==='medium') return 'זהו ממצא בעל משמעות בינונית. יש לברר את חומרתו ואת הטיפול הנדרש.';
  if(item?.reportSeverity==='low'||item?.reportSeverity==='minor') return 'זהו ממצא בעל משמעות נמוכה. יש לבדוק את מצב החלק ואת הטיפול הנדרש.';
  return 'יש לברר את משמעות הממצא אצל בעל המקצוע המתאים, בלי להסיק מעבר לנוסח הדוח.';
}

function customerSafeText(value,item,fallback='direction'){
  const sentences=String(value||'').split(/(?<=[.!?])/u).map(part=>part.trim()).filter(Boolean);
  const safe=sentences.filter(sentence=>!customerRestrictedWording.test(sentence)).join(' ').trim();
  if(safe) return safe;
  if(fallback==='meaning'){
    const source=String(item?.sourceText||item?.matchedTerm||'').trim();
    return source?`בדוח זוהה הנוסח „${source}”. הסיווג מבוסס על ההתאמה למאגר BuyTest.`:'הממצא סווג לפי הטקסט שנקרא מהדוח וההתאמה למאגר BuyTest.';
  }
  return neutralCustomerDirection(item);
}

function customerFacingDecision(item){
  return customerSafeText(item?.decision||professionalDecision({...item,decision:''}),item,'direction');
}

function rawFormulaToRule(formula,sourceLabel='מאגר הנוסחים'){
  const type=formula.classification?.type||formula.classification_type||'context_dependent';
  const formulaSeverity=['safety','high','medium','low','minor'].includes(formula.classification?.severity)?formula.classification.severity:null;
  const template=classificationTemplate(type,formula.category,formula.text);
  const safetyCategories=['מערכת הבלמים (ללא פירוק גלגלים)','מערכת ההיגוי','מערכת מתלה קדמי','מערכת מתלה אחורי','צמיגים וחישוקים','שלדת מרכב','שלדה נפרדת'];
  const rule={
    id:'formula-'+formula.id,
    category:formula.category,
    tag:formulaSeverity?reportSeverityLabels[formulaSeverity]:template.label,
    tone:formulaSeverity==='high'||(type==='actual_finding'&&safetyCategories.includes(formula.category))?'safety':'clarify',
    classification:type,
    reportSeverity:formulaSeverity,
    contextPolicy:formula.classification?.context_policy||null,
    meaning:formula.meaning||template.meaning,
    decision:formula.decision||'',
    question:formula.question||template.question,
    sourceText:formula.text,
    matchSource:sourceLabel
  };
  if(normalizeFindingText(formula.text)==='ריפוד'){
    rule.meaning='נרשם ממצא בריפוד תא הנוסעים. זהו ממצא בריפוד בלבד ואינו ממצא מבני או מכני.';
  }
  return applyExpertCalibration(rule,formula);
}

function customFormulaToRule(formula){
  const rule=rawFormulaToRule({
    ...formula,
    id:'custom-'+formula.id,
    classification:{type:formula.classification_type||'context_dependent',severity:formula.report_severity==='none'?null:formula.report_severity,context_policy:formula.classification_type==='context_dependent'?'vehicle_age_and_mileage':null}
  },'נוסח שהוסף בניהול');
  rule.managerMeaning=formula.meaning||'';
  rule.managerDecision=formula.decision||'';
  return rule;
}

function formulaMatchTokens(value){
  const stopWords=new Set(['של','או','על','עם','את','כללי','קד','אח']);
  return normalizeFindingText(value).split(' ').filter(Boolean).map(token=>{
    if(token.length>3&&/^[ובלכמ]/.test(token)) return token.slice(1);
    return token;
  }).filter(token=>token.length>1&&!stopWords.has(token));
}

function compactFindingText(value){
  return normalizeFindingText(value).replace(/\s/g,'');
}

function findingTextIncludes(normalizedLine,normalizedTerm){
  if(!normalizedLine||!normalizedTerm) return false;
  if(normalizedLine.includes(normalizedTerm)) return true;
  const compactTerm=normalizedTerm.replace(/\s/g,'');
  return compactTerm.length>=6&&normalizedLine.replace(/\s/g,'').includes(compactTerm);
}

function fuzzyFormulaScore(line,formulaText){
  const n=normalizeFindingText(line),term=normalizeFindingText(formulaText);
  if(!n||!term) return 0;
  if(findingTextIncludes(n,term)) return 1;
  const signalStems=['פגומ','לקוי','רעש','נזיל','חופש','שחוק','שבור','סד','דולק','חריק','נקיש','חלוד','קורוז','תקל','בדוק','כיוון','תיקונ','החלפ','סימנ','פתיח','מעיכ','שריט','הזע','רטיב','דליפ'];
  const lineSignals=signalStems.filter(stem=>n.includes(stem));
  const formulaSignals=signalStems.filter(stem=>term.includes(stem));
  if(!formulaSignals.length||!formulaSignals.some(stem=>lineSignals.includes(stem))) return 0;
  const lineTokens=formulaMatchTokens(n),formulaTokens=formulaMatchTokens(term);
  if(lineTokens.length<2||formulaTokens.length<2) return 0;
  const formulaSet=new Set(formulaTokens);
  const overlap=lineTokens.filter(token=>formulaSet.has(token)).length;
  if(overlap<2) return 0;
  const lineCoverage=overlap/lineTokens.length;
  const formulaCoverage=overlap/formulaTokens.length;
  return (lineCoverage*0.65)+(formulaCoverage*0.35);
}

function findKnowledgeRules(line,categoryHint=''){
  const n=normalizeFindingText(line);
  const matches=[];
  findingKnowledgeBase.forEach(rule=>{
    if(rule.categoryHints?.length&&!rule.categoryHints.includes(categoryHint)) return;
    let longest='';
    rule.terms.forEach(term=>{
      const normalizedTerm=normalizeFindingText(term);
      if(normalizedTerm&&findingTextIncludes(n,normalizedTerm)&&normalizedTerm.length>longest.length) longest=normalizedTerm;
    });
    if(!longest&&(rule.patterns||[]).some(pattern=>pattern.test(n))) longest=normalizeFindingText(rule.terms[0]||rule.id);
    if(longest){const matchedRule={...rule,classification:rule.classification||ruleClassification[rule.id]||'context_dependent',matchedTerm:longest,matchSource:'מאגר מקצועי'};matches.push(applyExpertCalibration(matchedRule,{id:rule.id,text:longest,terms:rule.terms}));}
  });

  const suppressed=new Set(matches.flatMap(item=>item.suppresses||[]));
  const curated=matches.filter(item=>!suppressed.has(item.id));
  const coveredTerms=curated.map(item=>item.matchedTerm);
  const additions=[];

  loadCustomFormulas().filter(isOperationalFormula).forEach(formula=>{
    const term=normalizeFindingText(formula.text);
    if(term&&findingTextIncludes(n,term)) additions.push(customFormulaToRule(formula));
  });

  observedFormulaAliases.filter(isOperationalFormula).forEach(alias=>{
    const term=normalizeFindingText(alias.text);
    if(!term||!findingTextIncludes(n,term)) return;
    const covered=coveredTerms.some(existing=>term.includes(existing)||existing.includes(term));
    if(!covered) additions.push(rawFormulaToRule({...alias,id:'alias-'+alias.id,classification:{type:alias.classification_type}},'נוסח שנמצא בבדיקות לדוגמה'));
  });

  rawFormulaDatabase.filter(isOperationalFormula).forEach(formula=>{
    const term=normalizeFindingText(formula.text);
    if(term.length<4||!findingTextIncludes(n,term)) return;
    const covered=coveredTerms.some(existing=>term.includes(existing)||existing.includes(term));
    if(!covered) additions.push(rawFormulaToRule(formula));
  });

  if(!curated.length&&!additions.length&&categoryHint){
    const fuzzy=rawFormulaDatabase.filter(formula=>isOperationalFormula(formula)&&formula.category===categoryHint)
      .map(formula=>({formula,score:fuzzyFormulaScore(n,formula.text)}))
      .filter(candidate=>candidate.score>=0.72)
      .sort((a,b)=>b.score-a.score||b.formula.text.length-a.formula.text.length);
    if(fuzzy.length){
      const best=fuzzy[0];
      additions.push(rawFormulaToRule(best.formula,'התאמה לנוסח המכון'));
    }
  }

  const preferred=[];
  const sourcePositions=new Map();
  [...curated,...additions].forEach(item=>{
    if(item.matchSource==='מאגר מקצועי'){preferred.push(item);return;}
    const sourceKey=normalizeFindingText(item.sourceText||'');
    if(!sourceKey){preferred.push(item);return;}
    if(!sourcePositions.has(sourceKey)){
      sourcePositions.set(sourceKey,preferred.length);
      preferred.push(item);
      return;
    }
    const position=sourcePositions.get(sourceKey);
    if(categoryHint&&item.category===categoryHint&&preferred[position]?.category!==categoryHint) preferred[position]=item;
  });

  const unique=[];
  const seen=new Set();
  preferred.forEach(item=>{
    const semanticKey=item.matchSource==='מאגר מקצועי'
      ? item.id
      : [item.category,item.classification,normalizeFindingText(item.sourceText||item.matchedTerm||item.id)].join('|');
    if(!seen.has(semanticKey)){
      seen.add(semanticKey);
      const enriched={...item,contextNote:contextNoteFor(item)};
      const specific=specificFindingInterpretation(enriched);
      if(specific){
        enriched.meaning=specific.meaning;
        enriched.decision=specific.decision;
      }else{
        enriched.decision=professionalDecision(enriched);
      }
      unique.push(enriched);
    }
  });
  return unique;
}

function reportCategoryFromLine(line){
  const n=normalizeFindingText(line).replace(/^\d+\s+/,'').trim();
  const compact=n.replace(/\s/g,'');
  if(compact.includes('הערותכלליות')) return 'הערות כלליות';
  if(/שלדה\s*ומ?רכ[בג]/.test(n)) return 'שלדת מרכב';
  if(/העברת\s*הכוח/.test(n)) return 'תיבת העברת הכוח';
  if(/סרן\s*קדמי.*היגוי/.test(n)) return 'מערכת ההיגוי';
  if(/^מערכת\s*קירור$/.test(n)) return 'מערכת הקירור';
  if(/^צמיגים$/.test(n)) return 'צמיגים וחישוקים';
  const matches=formulaCategoryDefinitions.filter(category=>{
    const categoryText=normalizeFindingText(category.name);
    if(!categoryText) return false;
    const categoryCompact=categoryText.replace(/\s/g,'');
    return n===categoryText||n.startsWith(categoryText+' ')||n.endsWith(' '+categoryText)||(categoryCompact.length>=6&&compact.includes(categoryCompact));
  }).sort((a,b)=>b.name.length-a.name.length);
  return matches[0]?.name||'';
}

function reportSeverityFromLine(line){
  const n=normalizeFindingText(line);
  if(/משמעות\s*גבוהה/.test(n)) return 'high';
  if(/משמעות\s*נמוכה/.test(n)) return 'low';
  if(/ליקויים?\s+שוליים?|ליקוי\s+שולי/.test(n)) return 'minor';
  return null;
}

function stripReportScaffolding(line,category,severity){
  let cleaned=normalizeFindingText(String(line||'').replace(/[✓✔☑×✕]/g,' '));
  if(category){
    const categoryText=normalizeFindingText(category);
    const withoutArticle=value=>value.replace(/^מערכת\s+ה/,'מערכת ');
    if(cleaned===categoryText||withoutArticle(cleaned)===withoutArticle(categoryText)||/שלדה\s*ומ?רכ[בג]/.test(cleaned)&&category==='שלדת מרכב') cleaned='';
    else if(cleaned.startsWith(categoryText+' ')) cleaned=cleaned.slice(categoryText.length).trim();
  }
  if(severity) cleaned=cleaned.replace(/משמעות\s*(?:גבוהה|נמוכה)|ליקויים?\s+שוליים?|ליקוי\s+שולי/g,' ');
  return cleaned.replace(/^\s*\d+\s*/,' ').replace(/\s+/g,' ').trim();
}

function isReportStatusScaffolding(value){
  const cleaned=normalizeFindingText(value)
    .replace(/(?:^|\s)(?:סטטוס|אבחנה|מכלול|הבדיקה|תקין|לא תקין|לא תקינה|כן|לא)(?=\s|$)/g,' ')
    .replace(/(?:^|\s)[0-9xv]+(?=\s|$)/g,' ')
    .replace(/\s+/g,' ')
    .trim();
  return !cleaned;
}

function specificFindingInterpretation(item){
  const source=normalizeFindingText(item?.sourceText||item?.matchedTerm||'');
  if(/תושבת\s+(?:תיבת\s+ה?ילוכים|גיר)\s+פגומ/.test(source)) return {
    meaning:'נרשמה תושבת פגומה של תיבת ההילוכים. התושבת מחברת את התיבה למרכב ומבודדת תנועה ורעידות; הממצא אינו קובע שתיבת ההילוכים עצמה פגומה.',
    decision:'יש לבדוק ולהחליף את התושבת לפי הצורך ולהביא בחשבון את עלות הטיפול. אין לסווג את תיבת ההילוכים כלא תקינה על סמך ממצא זה בלבד.'
  };
  if(/תיקוני פח(?:חות)? וצבע|בוצעו תיקוני פח וצבע/.test(source)) return {
    meaning:'נמצאו סימנים לעבודות פחחות וצבע בחלקים החיצוניים של הרכב. הנוסח אינו מצביע לבדו על החלפת חלק או על פגיעה מבנית.',
    decision:'יש לבדוק את איכות הצבע והפחחות ולהביא בחשבון תיקון קוסמטי אם נדרש.'
  };
  if(/מעיכות.*שריטות|שריטות.*מעיכות|פגמים ושריטות בצבע|שריטות קלות/.test(source)) return {
    meaning:'נמצאו מעיכות, שריטות או פגמי צבע בחלקים החיצוניים של הרכב. מדובר בתיאור של מצב המרכב החיצוני, ללא קביעה של נזק מבני.',
    decision:'יש להביא בחשבון את המצב הקוסמטי ואת עלות תיקוני הפח והצבע הרצויים.'
  };
  if(/שפשוף פגושים|תיקון נזק לפגושים|תיקון פגיעה בפגוש/.test(source)) return {
    meaning:'נרשם שפשוף או תיקון בפגוש. הפגוש הוא חלק חיצוני, והנוסח אינו מעיד לבדו על פגיעה במבנה הרכב.',
    decision:'יש לבדוק את מצב הפגוש, החיבורים והצבע ולהביא בחשבון תיקון קוסמטי לפי הצורך.'
  };
  if(/חלקי פלסטיק פגומים|פלסטיקה פגומה/.test(source)) return {
    meaning:'נרשם נזק בחלקי פלסטיק ברכב. הנוסח אינו מפרט אילו חלקים נפגעו או אם קיימת השפעה תפקודית.',
    decision:'יש לזהות את החלקים הפגומים ולבדוק אם נדרש חיזוק, תיקון או החלפה.'
  };
  if(/סימני פתיחת ברגים.*מכסה מנוע/.test(source)) return {
    meaning:'נמצאו סימני פתיחת ברגים במכסה המנוע. הדבר מצביע על פירוק או כיוון שבוצעו בעבר, אך אינו מוכיח לבדו החלפה או פגיעה מבנית.',
    decision:'יש לבדוק את התאמת המכסה, המרווחים והחיבורים, בלי להסיק מכך נזק מבני שלא נכתב בדוח.'
  };
  if(/חלודה במכללי הרכב|קורוזיה במכללי הרכב/.test(source)) return {
    meaning:'נרשמה חלודה במכלולי הרכב, אך הדוח אינו מפרט את מיקומה ואת היקפה.',
    decision:'יש לראות את האזור ולבדוק אם החלודה שטחית או מתקדמת ואם היא משפיעה על תפקוד החלק.'
  };
  return null;
}

function applyReportSeverity(item,severity,categoryHint){
  const chassisCategories=['שלדת מרכב','שלדה נפרדת'];
  if(!severity||!chassisCategories.includes(item.category)) return item;
  const resolvedCategory=chassisCategories.includes(categoryHint)?categoryHint:item.category;
  const enriched={...item,category:resolvedCategory,reportSeverity:severity,tag:reportSeverityLabels[severity]||item.tag};
  enriched.tone=severity==='high'?'safety':'clarify';
  const specific=specificFindingInterpretation(enriched);
  if(specific) enriched.meaning=specific.meaning;
  enriched.decision=specific?.decision||professionalDecision({...enriched,decision:''});
  return enriched;
}

function safeUnknownExcerpt(line){
  return String(line||'')
    .replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g,'[פרט הוסר]')
    .replace(/\b\d{7,}\b/g,'[מספר הוסר]')
    .replace(/\s+/g,' ')
    .trim()
    .slice(0,180);
}

function isSeverityHeadingOnly(value){
  const compact=normalizeFindingText(value).replace(/[^א-ת]/g,'');
  return compact==='משמעותנמוכה'||compact==='משמעותגבוהה'||compact==='ליקוישולי'||compact==='ליקוייםשוליים';
}

function finalizeReportFinding(item){
  if(!item) return null;
  const source=item.sourceText||item.matchedTerm||'';
  if(isSeverityHeadingOnly(source)||/^(?:high|low)-meaning$/.test(String(item.id||''))) return null;
  const headingDiagnosis=/הממצא מופיע בדוח המכון תחת|זהו הסיווג שנשמר|ממצא בדרגת משמעות (?:נמוכה|גבוהה) לפי סיווג המכון/;
  let cleaned={...item};
  if(headingDiagnosis.test((cleaned.meaning||'')+' '+(cleaned.decision||''))){
    if(!source) return null;
    const specific=specificFindingInterpretation(cleaned);
    if(specific){
      cleaned.meaning=specific.meaning;
      cleaned.decision=specific.decision;
    }else{
      cleaned.meaning='נרשם בדוח הממצא: „'+source+'”.';
      cleaned.decision=professionalDecision({...cleaned,meaning:cleaned.meaning,decision:''});
    }
  }
  return applyManagerFormulaOverride(cleaned);
}

function reportConclusionOrder(category){
  const value=normalizeFindingText(category);
  if(/מנוע|גידוש/.test(value)) return 10;
  if(/קירור/.test(value)) return 20;
  if(/דלק/.test(value)) return 30;
  if(/הצתה/.test(value)) return 40;
  if(/פליטה|זיהום/.test(value)) return 50;
  if(/התנעה|מצבר|טעינה/.test(value)) return 60;
  if(/מצמד/.test(value)) return 70;
  if(/תיבת|הילוכ|העברת הכוח/.test(value)) return 80;
  if(/צירי|גל הינע|הנעה/.test(value)) return 90;
  if(/מתלה קדמי|קפיצים קדמי/.test(value)) return 100;
  if(/מתלה אחורי|קפיצים אחורי/.test(value)) return 110;
  if(/מתל.*היגוי|היגוי.*מתל/.test(value)) return 120;
  if(/מתל|קפיצ/.test(value)) return 115;
  if(/היגוי/.test(value)) return 120;
  if(/בלמ/.test(value)) return 130;
  if(/צמיג|חישוק|גלגל/.test(value)) return 140;
  if(/שלד|מרכב|פח|צבע/.test(value)) return 150;
  if(/תאורה|פנס/.test(value)) return 160;
  if(/מחוונ|מחשב|אלקטרונ/.test(value)) return 170;
  if(/הערות|מגבלת/.test(value)) return 190;
  return 180;
}

function orderFindingsLikeReport(findings){
  return findings.map((item,index)=>({item,index,order:reportConclusionOrder(item.category||'')}))
    .sort((a,b)=>a.order-b.order||a.index-b.index)
    .map(entry=>entry.item);
}

function interpretSummaryText(text){
  const findings=[],unknown=[],seen=new Set();
  text=diagnosticTableText(text);
  const compactReport=normalizeFindingText(text).replace(/\s/g,'');
  const chassisHint=compactReport.includes('סוגשלדהשלדהנפרדת')?'שלדה נפרדת':compactReport.includes('סוגשלדהשלדתמרכב')?'שלדת מרכב':'';
  const chassisCategories=['שלדת מרכב','שלדה נפרדת'];
  let currentCategory='',currentSeverity=null,skipSection=false;
  const lines=reportLines(text);
  lines.forEach((line,index)=>{
    const lineCategory=reportCategoryFromLine(line);
    if(lineCategory){
      currentCategory=lineCategory;
      currentSeverity=chassisCategories.includes(lineCategory)?'low':null;
      skipSection=lineCategory==='הערות כלליות';
    }
    if(skipSection||lineCategory==='הערות כלליות') return;
    const lineSeverity=reportSeverityFromLine(line);
    if(lineSeverity){
      currentSeverity=lineSeverity;
      if(chassisHint) currentCategory=chassisHint;
    }
    const contentLine=stripReportScaffolding(line,lineCategory,lineSeverity);
    if(!contentLine||isReportStatusScaffolding(contentLine)||isExplicitlyNormal(contentLine)) return;
    const candidateLines=[contentLine];
    if(lines[index+1]) candidateLines.push(contentLine+' '+stripReportScaffolding(lines[index+1],reportCategoryFromLine(lines[index+1]),reportSeverityFromLine(lines[index+1])));
    if(lines[index+1]&&lines[index+2]) candidateLines.push(contentLine+' '+stripReportScaffolding(lines[index+1],reportCategoryFromLine(lines[index+1]),reportSeverityFromLine(lines[index+1]))+' '+stripReportScaffolding(lines[index+2],reportCategoryFromLine(lines[index+2]),reportSeverityFromLine(lines[index+2])));
    const rules=candidateLines.flatMap(candidate=>findKnowledgeRules(candidate,currentCategory));
    if(rules.length){
      rules.forEach(rule=>{
        const enriched=applyReportSeverity(rule,currentSeverity,currentCategory);
        const sourceKey=normalizeFindingText(enriched.sourceText||enriched.matchedTerm||enriched.meaning||'');
        const duplicateIndex=findings.findIndex(existing=>{
          if(existing.id!==enriched.id) return false;
          const existingSource=normalizeFindingText(existing.sourceText||existing.matchedTerm||existing.meaning||'');
          return existingSource===sourceKey||existingSource.includes(sourceKey)||sourceKey.includes(existingSource);
        });
        if(duplicateIndex>=0){
          const existing=findings[duplicateIndex];
          const existingSource=normalizeFindingText(existing.sourceText||existing.matchedTerm||existing.meaning||'');
          if(sourceKey.length>existingSource.length) findings[duplicateIndex]=enriched;
          return;
        }
        const findingKey=[enriched.id,sourceKey].join('|');
        if(!seen.has(findingKey)){findings.push(enriched);seen.add(findingKey);}
      });
    }else if(isPotentialUnknownFindingLine(contentLine)){
      const excerpt=safeUnknownExcerpt(contentLine);
      if(excerpt&&!unknown.includes(excerpt)) unknown.push(excerpt);
    }
  });
  const finalFindings=orderFindingsLikeReport(findings.map(finalizeReportFinding).filter(Boolean));
  return applyReportMileageContext(applyEngineWarrantyContext({findings:finalFindings,unknown},text),text);
}

