function extractDtcCodeDetails(text){
  const found=[];
  const source=String(text||'').toUpperCase();
  for(const match of source.matchAll(/\b([PCBU])[\s\-:.]*([0-9A-FOIL])[\s\-:.]*([0-9A-FOIL])[\s\-:.]*([0-9A-FOIL])[\s\-:.]*([0-9A-FOIL])(?:[\s\-:.]*([0-9A-FOIL])[\s\-:.]*([0-9A-FOIL]))?\b/g)){
    const code=match.slice(1,6).join('').replace(/[O]/g,'0').replace(/[IL]/g,'1');
    const extension=match[6]&&match[7]?(match[6]+match[7]).replace(/[O]/g,'0').replace(/[IL]/g,'1'):'';
    const displayCode=extension?`${code}-${extension}`:code;
    const existing=found.find(item=>item.code===code);
    if(!existing) found.push({code,displayCode,raw:match[0]});
    else if(extension&&!existing.displayCode.includes('-')) Object.assign(existing,{displayCode,raw:match[0]});
  }
  return found;
}

function extractDtcCodes(text){return extractDtcCodeDetails(text).map(item=>item.code)}

function dtcDisplayCode(text,code){
  return extractDtcCodeDetails(text).find(item=>item.code===code)?.displayCode||code;
}

function dtcContextForCode(text,code){
  const lines=cleanOcrText(text).split('\n').map(line=>line.trim()).filter(Boolean);
  const index=lines.findIndex(line=>extractDtcCodes(line).includes(code));
  if(index<0) return code;
  const selected=[lines[index]];
  for(const neighbor of [lines[index-1],lines[index+1]]){
    if(neighbor&&!extractDtcCodes(neighbor).length&&neighbor.length<=100&&detectDtcStatus(neighbor)==='unknown') selected.push(neighbor);
  }
  if(detectDtcStatus(lines[index])==='unknown'){
    let statusLine='';
    for(let distance=1;distance<=8;distance++){
      const previous=lines[index-distance];
      if(previous&&extractDtcCodes(previous).length&&detectDtcStatus(previous)!=='unknown') break;
      if(previous&&!extractDtcCodes(previous).length&&detectDtcStatus(previous)!=='unknown'){
        statusLine=previous;
        break;
      }
    }
    if(!statusLine){
      for(let distance=1;distance<=2;distance++){
        const next=lines[index+distance];
        if(next&&!extractDtcCodes(next).length&&detectDtcStatus(next)!=='unknown'){
          statusLine=next;
          break;
        }
      }
    }
    if(statusLine) selected.push(statusLine);
  }
  return selected.join(' · ');
}

function detectDtcStatus(context){
  const raw=String(context||'').toLowerCase();
  const n=normalizeFindingText(context);
  if(/לא\s+(?:פעיל|פעילה|נוכח|נוכחית|קיים|קיימת)|אינ(?:ו|ה)\s+(?:פעיל|פעילה|נוכח|נוכחת)|not\s+(?:present|current|active)|inactive|history|historical|historic|past|לסירוגין|היסטורי/.test(raw+' '+n)) return 'historical';
  if(/permanent|קוד\s+קבוע|תקלה\s+קבועה/.test(raw+' '+n)) return 'permanent';
  if(/pending|ממתינ|בהמתנה/.test(raw+' '+n)) return 'pending';
  if(/current|active|present|\bact\b|אקטיב(?:י|ית|יים|יות)?|תקלה\s+(?:פעילה|חיה)|תקלות\s+(?:פעילות|חיות)|פעיל\b|פעילה\b|פעילים\b|פעילות\b|נוכח\b|נוכחית\b|קיימת\s+כעת/.test(raw+' '+n)) return 'active';
  if(/confirmed|stored|mature|מאומת|שמורה|שמור\b/.test(raw+' '+n)) return 'confirmed';
  return 'unknown';
}

function fallbackDtcKnowledge(code){
  const manufacturerSpecific=/^[PCBU][13]/.test(code);
  const suffix=manufacturerSpecific?' הפירוש המדויק עשוי להשתנות לפי היצרן, הדגם וסוג מחשב הרכב.':'';
  if(/^P0[A-D]/.test(code)) return {system:'מערכת היברידית / חשמלית',title:'קוד במערכת ההנעה המחושמלת',severity:'high',direction:'הקוד שייך למשפחת בקרת ההנעה ההיברידית או החשמלית.'+suffix,checks:['תיאור הקוד בכלי האבחון המתאים ליצרן','מצבר 12 וולט','קודים נלווים בכל בקרי ההנעה','נתוני סוללה ומתח גבוה','בדיקה בידי בעל הסמכה כאשר מעורב מתח גבוה']};
  if(/^P03/.test(code)) return {system:'מנוע / הצתה ובעירה',title:'קוד במשפחת ההצתה או הבעירה',severity:'high',direction:'הקוד שייך למשפחה הכוללת החטאות הצתה, סנכרון או מעגלי הצתה.'+suffix,checks:['תיאור היצרן המדויק','נתוני Freeze Frame','מוני החטאה','הצתה והזרקה','דחיסה ותזמון']};
  if(/^P04|^P2(?:0|2|4)/.test(code)) return {system:'זיהום אוויר',title:'קוד במערכת בקרת הפליטה',severity:'medium',direction:'הקוד שייך למשפחה הכוללת EGR, ממיר, חיישני פליטה, EVAP, DPF או SCR.'+suffix,checks:['תיאור הקוד המדויק','קודים נלווים','נתוני חיישנים חיים','דליפות וסתימות','מוכנות מערכות הזיהום']};
  if(/^P0[78]|^P1[78]/.test(code)) return {system:'תיבת הילוכים',title:'קוד במערכת תיבת ההילוכים',severity:'high',direction:'הקוד שייך למשפחת הבקרה החשמלית, ההידראולית או יחסי ההעברה בתיבת ההילוכים.'+suffix,checks:['סריקה ישירה של מחשב התיבה','מצב הקוד','מהירויות כניסה ויציאה','לחצים וטמפרטורה','חיווט וסולנואידים','התאמות ובלאי רק לאחר בדיקות מקדימות']};
  if(/^P0[0-2]|^P05|^P06|^P[123]/.test(code)) return {system:'מנוע / מערכת הנעה',title:'קוד במערכת ניהול המנוע או ההנעה',severity:'medium',direction:'הקוד שייך לניהול אוויר, דלק, חיישנים, פיקוד מנוע או מערכת הנעה.'+suffix,checks:['תיאור היצרן המדויק','מצב הקוד ו־Freeze Frame','נתונים חיים','הזנות וחיווט','בדיקה מכנית רק לפי הממצאים']};
  if(/^U/.test(code)) return {system:'תקשורת בין מחשבים',title:'קוד תקשורת או רשת נתונים',severity:'medium',direction:'אחד ממחשבי הרכב דיווח על הודעה חסרה, תקשורת לא תקינה או נתון לא סביר.'+suffix,checks:['מתח מצבר וטעינה','הזנות והארקות','רשת CAN ומחברים','סריקה מלאה של כל המחשבים','הפרדה בין אירוע היסטורי לתקלה פעילה']};
  if(/^C/.test(code)) return {system:'שלדה ובטיחות',title:'קוד במערכת שלדה',severity:'high',direction:'הקוד שייך בדרך כלל למערכות ABS, יציבות, היגוי, מתלים או חיישני שלדה.'+suffix,checks:['תיאור היצרן המדויק','נורות אזהרה','נתונים חיים וחיישני גלגל','חיווט ומחברים','בדיקה ישירה של המערכת']};
  return {system:'מרכב ובטיחות',title:'קוד במערכת מרכב',severity:'medium',direction:'הקוד שייך בדרך כלל לכריות אוויר, נעילה, תאורה, מיזוג או מערכות מרכב.'+suffix,checks:['תיאור היצרן המדויק','מצב הקוד','נורות אזהרה','הזנות וחיווט','בדיקה ישירה של המחשב הרלוונטי']};
}

function dtcKnowledgeFor(code){
  return dtcKnowledgeBase.find(item=>item.match.test(code))||fallbackDtcKnowledge(code);
}

function dtcFinding(code,text){
  const knowledge=dtcKnowledgeFor(code);
  const displayCode=dtcDisplayCode(text,code);
  const statusKey=detectDtcStatus(dtcContextForCode(text,code));
  const status=dtcStatusDefinitions[statusKey];
  const highImpact=['safety','high'].includes(knowledge.severity)&&statusKey!=='historical';
  return {
    id:'dtc-'+code,
    code,
    displayCode,
    dtcStatusKey:statusKey,
    dtcSeverity:knowledge.severity,
    category:knowledge.system,
    tag:status.label+' · '+dtcSeverityLabels[knowledge.severity],
    tone:highImpact?'safety':'clarify',
    classification:'computer_diagnostic_code',
    reportSeverity:knowledge.severity,
    meaning:`קוד ${displayCode} — ${knowledge.title}. כיוון כללי: ${knowledge.direction}`,
    decision:knowledge.checks.join(', ')+'. אין להחליף רכיב על סמך הקוד בלבד.',
    contextNote:status.explanation,
    sourceText:code
  };
}

function dtcClusterFindings(codes){
  const findings=[];
  const communication=codes.filter(code=>code.startsWith('U'));
  const hasSystemVoltageCode=codes.some(code=>/^P056[0-3]$/.test(code));
  if(communication.length>=2&&!hasSystemVoltageCode){
    findings.push({id:'dtc-cluster-communication',dtcStatusKey:'overview',category:'תמונה משולבת',tag:'קשר בין קודים',tone:'clarify',classification:'computer_code_cluster',meaning:`נמצאו ${communication.length} קודי תקשורת במקביל (${communication.join(', ')}). ריבוי קודים כאלה עשוי לנבוע מגורם משותף ולא מתקלה נפרדת בכל מחשב.`,decision:'יש לבדוק תחילה מתח מצבר וטעינה, הזנות והארקות, מצב רשת התקשורת ומועד הופעת הקודים; רק אחר כך לבודד מחשב מסוים.'});
  }
  if(communication.length&&hasSystemVoltageCode){
    findings.push({id:'dtc-cluster-voltage',dtcStatusKey:'overview',category:'תמונה משולבת',tag:'קשר בין קודים',tone:'clarify',classification:'computer_code_cluster',meaning:'קוד מתח מערכת מופיע יחד עם קוד או קודי תקשורת. ייתכן שהפרעת המתח יצרה חלק מקודי התקשורת, במיוחד אם כולם נרשמו באותו אירוע.',decision:'יש לייצב ולבדוק את מערכת ה־12 וולט, למחוק קודים רק לאחר תיעוד, לבצע נסיעת אימות ולבדוק אילו קודים חוזרים לפני קביעה על מחשב או רשת תקשורת.'});
  }
  const misfire=codes.some(code=>/^P03(?:0[0-9]|1[0-2])$/.test(code));
  const mixture=codes.some(code=>/^P017[1245]$/.test(code));
  const catalyst=codes.some(code=>/^P04(?:20|30)$/.test(code));
  if(misfire&&(mixture||catalyst)){
    findings.push({id:'dtc-cluster-combustion',dtcStatusKey:'overview',category:'תמונה משולבת',tag:'קשר בין קודים',tone:'safety',classification:'computer_code_cluster',meaning:'קודי החטאת הצתה מופיעים יחד עם קוד תערובת או יעילות ממיר. קוד הממיר עשוי להיות תוצאה של בעירת מנוע לא תקינה ולא בהכרח התקלה הראשונית.',decision:'יש לאבחן תחילה את ההחטאות, התערובת וכניסת האוויר, ורק לאחר תיקון ואימות לחזור ולבדוק את יעילות הממיר.'});
  }
  if(codes.includes('P0700')&&codes.some(code=>/^P07(?!00)|^P08/.test(code))){
    findings.push({id:'dtc-cluster-transmission',dtcStatusKey:'overview',category:'תמונה משולבת',tag:'קשר בין קודים',tone:'clarify',classification:'computer_code_cluster',meaning:'הקוד P0700 הוא הודעת הפניה ממחשב תיבת ההילוכים; הקודים הנוספים של התיבה הם המקור המפורט יותר לכיוון האבחון.',decision:'יש לתת עדיפות לקודים הישירים ממחשב התיבה ולנתוני ההחלקה, הלחץ, הטמפרטורה והמהירויות שנלווים אליהם.'});
  }
  return findings;
}

function compactVehicleIdentifier(value){
  return String(value||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
}

function validVin(value){
  const compact=compactVehicleIdentifier(value);
  return /^[A-HJ-NPR-Z0-9]{17}$/.test(compact)?compact:'';
}

function usefulVehicleValue(value){
  const cleaned=String(value||'').replace(/^[\s:#\-–—]+|[\s|;,]+$/g,'').replace(/\s{2,}/g,' ').trim();
  if(!cleaned||cleaned.length<2||cleaned.length>70) return '';
  if(/^(לא זמין|לא צוין|unknown|n\/a)/i.test(cleaned)) return '';
  return cleaned;
}

function extractComputerVehicleIdentity(text){
  const raw=cleanOcrText(text);
  const lines=raw.split('\n').map(line=>line.trim()).filter(Boolean);
  let vin='',plate='',maker='',model='',year='';

  for(const line of lines){
    if(!vin){
      const match=line.match(/(?:\bVIN\b|מספר\s*שלדה|מס[׳'\.]?\s*שלדה|שלדת\s*רכב|chassis(?:\s*(?:no|number))?|vehicle\s*identification\s*number)\s*[:#\-–—]?\s*([A-Z0-9][A-Z0-9\s\-]{15,32})/i);
      if(match){
        const candidates=String(match[1]).toUpperCase().match(/[A-Z0-9][A-Z0-9\s\-]{15,32}/g)||[];
        for(const candidate of candidates){
          const compact=compactVehicleIdentifier(candidate);
          if(compact.length>=17){
            for(let start=0;start<=compact.length-17;start++){
              const possible=validVin(compact.slice(start,start+17));
              if(possible){vin=possible;break;}
            }
          }
          if(vin) break;
        }
      }
    }
    if(!plate){
      const match=line.match(/(?:מספר\s*(?:רכב|רישוי|רישיון|רשיון)|מס[׳'\.]?\s*(?:רכב|רישוי)|license\s*plate|registration\s*(?:no|number)|plate\s*(?:no|number)?)\s*[:#\-–—]?\s*((?:\d[\s\-]*){7,8})/i);
      if(match){
        const possible=String(match[1]).replace(/\D/g,'');
        if(/^\d{7,8}$/.test(possible)) plate=possible;
      }
    }
    if(!maker){
      const match=line.match(/(?:^|\s)(?:יצרן|תוצרת|manufacturer|make)\s*[:#\-–—]+\s*(.+)$/i);
      if(match) maker=usefulVehicleValue(match[1]);
    }
    if(!model){
      const match=line.match(/(?:^|\s)(?:דגם\s*רכב|דגם|vehicle\s*model|model)\s*[:#\-–—]+\s*(.+)$/i);
      if(match) model=usefulVehicleValue(match[1]);
    }
  }

  if(!maker||!model||!year){
    let match=null;
    for(const line of lines){
      const candidate=line.match(/^([A-Za-z][A-Za-z.\-]{1,20})\s+([A-Za-z0-9][A-Za-z0-9 .()/_\-]{1,35}?)\s+((?:19|20)\d{2})(?:\s|$)/);
      if(candidate&&!/(system|function|report|diagnostic|version|automatically)/i.test(candidate[1]+' '+candidate[2])){match=candidate;break;}
    }
    if(match){
      if(!maker) maker=usefulVehicleValue(match[1]);
      if(!model) model=usefulVehicleValue(match[2]);
      if(!year) year=match[3];
    }
  }

  if(!vin){
    const candidates=raw.toUpperCase().match(/\b[A-HJ-NPR-Z0-9]{17}\b/g)||[];
    vin=candidates.map(validVin).find(Boolean)||'';
  }
  return {vin,plate,maker,model,year};
}

function currentVehicleIdentity(){ return {}; }

function comparableVehicleText(value){
  return normalizeFindingText(String(value||'')).replace(/0/g,'o').replace(/[^a-z0-9א-ת]/g,'');
}

function assessComputerVehicleIdentity(extracted,expected={}){
  const evidence=[];
  if(extracted.vin) evidence.push(`מספר שלדה שנקרא מהדוח: ${extracted.vin}`);
  if(extracted.plate) evidence.push(`מספר רכב שנקרא מהדוח: ${extracted.plate}`);
  if(extracted.maker) evidence.push(`יצרן שנקרא מהדוח: ${extracted.maker}`);
  if(extracted.model) evidence.push(`דגם שנקרא מהדוח: ${extracted.model}`);
  if(extracted.year) evidence.push(`שנת ייצור שנקראה מהדוח: ${extracted.year}`);

  const vinComparable=Boolean(extracted.vin&&expected.vin);
  const plateComparable=Boolean(extracted.plate&&expected.plate);
  const vinMatch=vinComparable&&extracted.vin===expected.vin;
  const plateMatch=plateComparable&&extracted.plate===expected.plate;
  const vinMismatch=vinComparable&&!vinMatch;
  const plateMismatch=plateComparable&&!plateMatch;
  const expectedMaker=comparableVehicleText(expected.maker);
  const expectedModel=comparableVehicleText(expected.model);
  const reportMaker=comparableVehicleText(extracted.maker);
  const reportModel=comparableVehicleText(extracted.model);
  const makerMatch=Boolean(expectedMaker&&reportMaker&&(expectedMaker.includes(reportMaker)||reportMaker.includes(expectedMaker)));
  const modelMatch=Boolean(expectedModel&&reportModel&&(expectedModel.includes(reportModel)||reportModel.includes(expectedModel)));

  if(vinMismatch||plateMismatch){
    const fields=[vinMismatch?'מספר השלדה':'',plateMismatch?'מספר הרכב':''].filter(Boolean).join(' ו');
    return {status:'mismatch',title:'⚠ פרטי הדוח אינם תואמים לרכב שנבדק',message:`${fields} שנקראו מהבדיקה הממוחשבת אינם תואמים לנתוני הרכב. ייתכן שזה דוח של רכב אחר או שגיאת פענוח; אין להסתמך על התקלות לפני אימות מול הדוח המקורי ורישיון הרכב.`,evidence,extracted,expected};
  }
  if(vinMatch||plateMatch){
    const basis=vinMatch?'מספר השלדה':'מספר הרכב';
    return {status:'match',title:'✓ הבדיקה הממוחשבת תואמת לרכב',message:`ההתאמה אומתה לפי ${basis} שנקרא מהדוח.`,evidence,extracted,expected};
  }
  if(modelMatch||makerMatch){
    return {status:'partial',title:'זוהתה התאמה חלקית בלבד',message:'היצרן או הדגם שנקראו מהדוח תואמים לנתוני הרכב, אך לא נמצא מספר שלדה או מספר רכב שניתן להשוות. זו אינה הוכחה שהדוח שייך לרכב המסוים.',evidence,extracted,expected};
  }
  if(extracted.vin||extracted.plate){
    return {status:'unverified',title:'זוהה מזהה בדוח, אך לא ניתן לאמת אותו אוטומטית',message:'יש להשוות את המספר שנקרא מהדוח לרישיון הרכב. עד לאימות הידני אין לקבוע שהבדיקה שייכת לרכב.',evidence,extracted,expected};
  }
  return {status:'unverified',title:'לא ניתן לאמת לאיזה רכב שייכת הבדיקה',message:'לא נמצא בבדיקה הממוחשבת מספר שלדה או מספר רכב קריא. דגם בלבד אינו מספיק לאימות, ולכן יש לבדוק את דוח המקור מול רישיון הרכב.',evidence,extracted,expected};
}

function computerIdentityHtml(identity){
  if(!identity) return '';
  const evidence=identity.evidence?.length?`<p class="reportIdentityEvidence">${identity.evidence.map(escapeHtml).join(' · ')}</p>`:'';
  return `<section class="reportIdentityCheck ${escapeHtml(identity.status)}"><h5>${escapeHtml(identity.title)}</h5><p>${escapeHtml(identity.message)}</p>${evidence}</section>`;
}

function computerIdentityText(identity){
  if(!identity) return '';
  return ['אימות שיוך הבדיקה לרכב',identity.title,identity.message,...(identity.evidence||[])].filter(Boolean).join('\n');
}

const computerDescriptionKnowledgeBase=[
  {id:'computer-text-o2-rich',pattern:/\b(?:o2|02|oxygen)\s*sensor\s*signal\s*stuck\s*rich\b/i,system:'מנוע / תערובת וזיהום אוויר',title:'אות חיישן חמצן תקוע על תערובת עשירה',severity:'medium',direction:'המלל מצביע על אות חיישן חמצן או למבדה שנשאר בצד העשיר. ייתכן שמדובר בתערובת עשירה בפועל, בחיישן או במעגל שלו.',checks:['מצב התקלה ו־Freeze Frame','תיקוני דלק','תגובת החיישן','לחץ דלק ומזרקים','שסתום EVAP','חיווט ומחבר']},
  {id:'computer-text-o2-lean',pattern:/\b(?:o2|02|oxygen)\s*sensor\s*signal\s*stuck\s*lean\b/i,system:'מנוע / תערובת וזיהום אוויר',title:'אות חיישן חמצן תקוע על תערובת ענייה',severity:'medium',direction:'המלל מצביע על אות חיישן חמצן או למבדה שנשאר בצד העני. ייתכן שמדובר בתערובת ענייה בפועל, בדליפת אוויר, בחיישן או במעגל שלו.',checks:['מצב התקלה ו־Freeze Frame','תיקוני דלק','דליפות יניקה','לחץ דלק','תגובת החיישן','חיווט ומחבר']},
  {id:'computer-text-misfire',pattern:/\b(?:random|multiple|cylinder\s*\d+)?\s*misfire\s*(?:detected)?\b/i,system:'מנוע / הצתה ובעירה',title:'זוהתה החטאת הצתה',severity:'high',direction:'המלל מצביע על בעירה לא תקינה בצילינדר אחד או יותר, אך אינו קובע אם המקור הוא הצתה, דלק או מצב מכני.',checks:['מוני החטאה','מצתים וסלילים','הזרקה ולחץ דלק','דליפות אוויר','דחיסה ותזמון']},
  {id:'computer-text-catalyst',pattern:/\bcatalyst\s+(?:system\s+)?efficiency\s+below\s+threshold\b/i,system:'זיהום אוויר',title:'יעילות הממיר הקטליטי מתחת לסף',severity:'medium',direction:'המלל מצביע על יעילות נמוכה לפי השוואת חיישני הפליטה. אין להסיק ממנו לבדו שהממיר פגום.',checks:['החטאות ותערובת','דליפות פליטה','חיישני חמצן','טמפרטורת הממיר','בדיקת גזים']},
  {id:'computer-text-mixture',pattern:/\bsystem\s+too\s+(?:lean|rich)\b/i,system:'מנוע / תערובת דלק',title:'תערובת דלק ענייה או עשירה',severity:'medium',direction:'המלל מצביע על תיקוני דלק שהגיעו לגבול. חיישן החמצן הוא רק אחד הגורמים האפשריים.',checks:['STFT ו־LTFT','דליפות יניקה או פליטה','לחץ דלק ומזרקים','מד זרימת אוויר','חיישני חמצן']},
  {id:'computer-text-communication',pattern:/\b(?:lost|no)\s+communication\s+with\b/i,system:'תקשורת בין מחשבים',title:'אובדן תקשורת עם מחשב ברכב',severity:'high',direction:'המלל מצביע על תקשורת חסרה עם יחידת בקרה, אך ייתכן שהמקור הוא מתח, הזנה, הארקה, חיווט או רשת התקשורת.',checks:['מצבר וטעינה','הזנות והארקות','רשת CAN','מחברים וחיווט','סריקה מלאה של כל המחשבים']},
  {id:'computer-text-gear-ratio',pattern:/\b(?:incorrect|implausible)\s+(?:gear\s+)?ratio\b/i,system:'תיבת הילוכים',title:'יחס העברה לא תקין',severity:'high',direction:'המלל מצביע על פער בין יחס ההעברה המבוקש ליחס שנמדד. ייתכן קשר להחלקה, לחץ, פיקוד או חיישן.',checks:['מהירויות כניסה ויציאה','החלקה בנסיעה','לחץ ושמן גיר','סולנואידים וגוף שסתומים','חיישנים וחיווט']}
];

function computerDescriptionFindings(text){
  const findings=[],seen=new Set();
  reportLines(text).forEach(line=>{
    if(extractDtcCodes(line).length||/\bnormal\b/i.test(line)) return;
    const rule=computerDescriptionKnowledgeBase.find(item=>item.pattern.test(line));
    if(!rule||seen.has(rule.id)) return;
    seen.add(rule.id);
    const statusKey=detectDtcStatus(line);
    const status=dtcStatusDefinitions[statusKey]||dtcStatusDefinitions.unknown;
    findings.push({
      id:rule.id,computerDescription:true,dtcStatusKey:statusKey,dtcSeverity:rule.severity,
      category:rule.system,tag:`${status.label} · ${dtcSeverityLabels[rule.severity]}`,
      tone:['safety','high'].includes(rule.severity)&&statusKey!=='historical'?'safety':'clarify',
      classification:'computer_diagnostic_description',reportSeverity:rule.severity,
      meaning:`${rule.title}. כיוון כללי: ${rule.direction}`,
      decision:rule.checks.join(', ')+'. אין להחליף רכיב על סמך המלל בלבד.',
      contextNote:status.explanation,sourceText:line
    });
  });
  return findings;
}

function interpretComputerText(text,expected={}){
  const unknown=[];
  const codes=extractDtcCodes(text);
  const findings=[...dtcClusterFindings(codes),...codes.map(code=>dtcFinding(code,text)),...computerDescriptionFindings(text)];
  let genericAbnormalAdded=false;
  reportLines(text).forEach(line=>{
    if(isMetadataLine(line)||extractDtcCodes(line).length) return;
    const n=normalizeFindingText(line);
    if(/(לא תקין|נכשל|חריגה|חריג|מחוץ לטווח)/.test(n)&&!genericAbnormalAdded){
      findings.push({id:'computer-explicit-abnormal',dtcStatusKey:'generic',category:'בדיקה ממוחשבת',tag:'סומן כחריג',tone:'clarify',classification:'computer_abnormal_result',meaning:'בדף התוצאה סומנה חריגה מפורשת ללא קוד מלא שניתן לזהות בבטחה.',decision:'יש לזהות את שם המדד, היחידה וטווח הייחוס לפני שיוך החריגה לרכיב או למערכת מסוימת.'});
      genericAbnormalAdded=true;
      return;
    }
    if(!/(לא תקין|אינו תקין)/.test(n)&&/(^|\s)(תקין|עבר)(\s|$)/.test(n)) return;
    if(isPotentialUnknownFindingLine(line)){
      const excerpt=safeUnknownExcerpt(line);
      if(excerpt&&!unknown.includes(excerpt)) unknown.push(excerpt);
    }
  });
  findings.sort((a,b)=>(dtcStatusDefinitions[a.dtcStatusKey||'generic']?.order||99)-(dtcStatusDefinitions[b.dtcStatusKey||'generic']?.order||99));
  const vehicleIdentity=assessComputerVehicleIdentity(extractComputerVehicleIdentity(text),expected);
  return {findings,unknown,codes,vehicleIdentity};
}

function cors(origin){return {
  "Access-Control-Allow-Origin":origin===ALLOWED_ORIGIN?origin:ALLOWED_ORIGIN,
  "Access-Control-Allow-Headers":"authorization, apikey, content-type, x-buytest-manager-pin",
  "Access-Control-Allow-Methods":"POST, OPTIONS",
  "Access-Control-Max-Age":"86400",
  "Vary":"Origin",
  "Cache-Control":"no-store",
  "Content-Type":"application/json; charset=utf-8"
}}
function json(origin,body,status=200){return new Response(JSON.stringify(body),{status,headers:cors(origin)})}
async function sha256(value){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value||'')));return Array.from(new Uint8Array(digest)).map(byte=>byte.toString(16).padStart(2,'0')).join('')}
function b64urlBytes(value){const normalized=value.replace(/-/g,'+').replace(/_/g,'/');const padded=normalized+'='.repeat((4-normalized.length%4)%4);const binary=atob(padded);return Uint8Array.from(binary,char=>char.charCodeAt(0))}
function b64urlText(value){return new TextDecoder().decode(b64urlBytes(value))}
async function serviceRequest(path,init={}){if(!SUPABASE_URL||!SERVICE_ROLE_KEY)throw new Error('server_configuration_missing');const headers=new Headers(init.headers);headers.set('apikey',SERVICE_ROLE_KEY);headers.set('Authorization','Bearer '+SERVICE_ROLE_KEY);if(!headers.has('Content-Type'))headers.set('Content-Type','application/json');const response=await fetch(SUPABASE_URL+path,{...init,headers});const text=await response.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}if(!response.ok){console.error('BuyTest analyzer database request failed',response.status,path);throw new Error('database_request_failed')}return data}
async function privateConfig(name){const value=await serviceRequest('/rest/v1/rpc/buytest_get_private_config',{method:'POST',body:JSON.stringify({p_name:name})});return typeof value==='string'?value:''}
async function orderById(id){const data=await serviceRequest('/rest/v1/buytest_orders?id=eq.'+encodeURIComponent(id)+'&select=id,plate,plan,status',{method:'GET'});return Array.isArray(data)?data[0]:null}
async function verifyEntitlement(token){const parts=String(token||'').split('.');if(parts.length!==2)return null;let payload;try{payload=JSON.parse(b64urlText(parts[0]))}catch{return null}if(!payload?.oid||!payload?.plate||!Array.isArray(payload?.scopes)||Number(payload.exp)<Math.floor(Date.now()/1000))return null;const secret=await privateConfig('buytest_entitlement_hmac_secret');if(!secret)return null;const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);const valid=await crypto.subtle.verify('HMAC',key,b64urlBytes(parts[1]),new TextEncoder().encode(parts[0]));if(!valid)return null;const order=await orderById(String(payload.oid));if(!order||order.status!=='paid'||order.plate!==String(payload.plate)||order.plan!==String(payload.plan))return null;return payload}
async function isAdmin(pin){const expected=await privateConfig('buytest_manager_pin_hash');return Boolean(pin)&&Boolean(expected)&&await sha256(String(pin).trim())===expected}
async function overrides(){const data=await serviceRequest('/rest/v1/buytest_formula_overrides?active=eq.true&select=*',{method:'GET'});return Array.isArray(data)?data:[]}
function applyServerOverrides(result,rows){if(!result?.findings?.length||!rows.length)return result;const bySource=new Map(rows.map(row=>[formulaOverrideKey(row.category,row.source_text),row]));return {...result,findings:result.findings.map(item=>{const source=item.sourceText||item.matchedTerm||'';const row=bySource.get(formulaOverrideKey(item.category,source));if(!row)return item;return {...item,classification:row.classification_type||item.classification,reportSeverity:row.report_severity==='none'?null:(row.report_severity||item.reportSeverity),tag:row.report_severity?(expertSeverityLabels[row.report_severity]||item.tag):item.tag,meaning:row.meaning||item.meaning,decision:row.decision||item.decision,question:row.question||item.question,managerEdited:true}})} }
function applyCustomRules(text,result,rows){const custom=rows.filter(row=>row.source_kind==='custom'&&row.active!==false);if(!custom.length)return result;const normalized=normalizeFindingText(text);const findings=[...(result?.findings||[])];for(const row of custom){const term=normalizeFindingText(row.source_text);if(term.length<3||!normalized.includes(term))continue;if(findings.some(item=>formulaOverrideKey(item.category,item.sourceText||item.matchedTerm||'')===formulaOverrideKey(row.category,row.source_text)))continue;findings.push({id:'custom-'+row.source_id,category:row.category,tag:expertSeverityLabels[row.report_severity]||formulaClassificationLabels[row.classification_type]||'סיווג מקצועי',tone:['safety','high'].includes(row.report_severity)?'safety':'clarify',classification:row.classification_type,reportSeverity:row.report_severity==='none'?null:row.report_severity,meaning:row.meaning||'נמצא ניסוח שהוגדר במאגר המקצועי.',decision:row.decision||'יש לברר את הממצא אצל בעל המקצוע המתאים.',question:row.question||'',sourceText:row.source_text,managerEdited:true})}return {...result,findings:orderFindingsLikeReport(findings.map(finalizeReportFinding).filter(Boolean))}}
function sourceGroundedSummaryResult(result,text){
  const report=normalizeFindingText(text);
  const findings=(result?.findings||[]).filter(item=>{
    const observed=normalizeFindingText(item?.observedText||'');
    const source=normalizeFindingText(item?.sourceText||item?.matchedTerm||'');
    const descriptor=normalizeFindingText([item?.id,item?.category,item?.title,item?.matchedTerm,item?.sourceText].filter(Boolean).join(' '));
    if(!/מזגן|מיזוג|aircon/.test(descriptor)) return true;
    if(/מדחס מזגן/.test(descriptor)&&!/מדחס מזגן/.test(report)) return false;
    const evidence=observed&&report.includes(observed)?observed:source&&report.includes(source)?source:'';
    return /(?:מזגן|מיזוג).*(?:לא מקרר|לא תקין|אינו פועל|לא פועל|מנותק|חסר גז|בדוק|תקן|תקלה)|(?:לא מקרר|לא תקין|אינו פועל|לא פועל|מנותק|חסר גז|בדוק|תקן|תקלה).*(?:מזגן|מיזוג)/.test(evidence);
  });
  return {...result,findings};
}

function adminCatalog(){const base=rawFormulaDatabase.filter(isOperationalFormula).map(item=>({source_kind:'formula',source_id:item.id,category:item.category,source_text:item.text,classification_type:item.classification?.type||'context_dependent',report_severity:item.classification?.severity==='review'?'medium':(item.classification?.severity||'none'),meaning:item.meaning||'',decision:item.decision||'',question:item.question||''}));const observed=observedFormulaAliases.filter(isOperationalFormula).map(item=>({source_kind:'observed',source_id:item.id,category:item.category,source_text:item.text,classification_type:item.classification_type||'context_dependent',report_severity:item.report_severity||'none',meaning:item.meaning||'',decision:item.decision||'',question:item.question||''}));return [...observed,...base]}
async function saveOverride(body){const row={source_kind:String(body.source_kind||''),source_id:String(body.source_id||''),category:String(body.category||'').slice(0,100),source_text:String(body.source_text||'').slice(0,500),classification_type:String(body.classification_type||'context_dependent').slice(0,80),report_severity:String(body.report_severity||'none'),meaning:String(body.meaning||'').slice(0,2000),decision:String(body.decision||'').slice(0,2000),question:String(body.question||'').slice(0,1000),active:true,updated_at:new Date().toISOString()};if(!['knowledge','formula','observed','custom'].includes(row.source_kind)||!row.source_id||!row.category||row.source_text.length<3||!['safety','high','medium','low','none'].includes(row.report_severity))throw new Error('invalid_override');const data=await serviceRequest('/rest/v1/buytest_formula_overrides?on_conflict=source_kind,source_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=representation'},body:JSON.stringify(row)});return Array.isArray(data)?data[0]:null}
async function deleteOverride(body){const sourceKind=String(body.source_kind||'');const sourceId=String(body.source_id||'');if(!['knowledge','formula','observed','custom'].includes(sourceKind)||!sourceId)throw new Error('invalid_override');await serviceRequest('/rest/v1/buytest_formula_overrides?source_kind=eq.'+encodeURIComponent(sourceKind)+'&source_id=eq.'+encodeURIComponent(sourceId),{method:'DELETE',headers:{Prefer:'return=minimal'}});return true}

Deno.serve(async req=>{const origin=req.headers.get('origin');if(req.method==='OPTIONS'){if(origin!==ALLOWED_ORIGIN)return json(origin,{ok:false,error:'origin_not_allowed'},403);return new Response(null,{status:204,headers:cors(origin)})}if(req.method!=='POST')return json(origin,{ok:false,error:'method_not_allowed'},405);if(origin!==ALLOWED_ORIGIN)return json(origin,{ok:false,error:'origin_not_allowed'},403);let body;try{body=await req.json()}catch{return json(origin,{ok:false,error:'invalid_json'},400)}try{const admin=await isAdmin(req.headers.get('x-buytest-manager-pin')||body.adminPin);if(body.action==='adminCatalog'){if(!admin)return json(origin,{ok:false,error:'admin_denied'},403);return json(origin,{ok:true,rows:adminCatalog(),overrides:await overrides()})}if(body.action==='adminSaveOverride'){if(!admin)return json(origin,{ok:false,error:'admin_denied'},403);return json(origin,{ok:true,row:await saveOverride(body.row||{})})}if(body.action==='adminDeleteOverride'){if(!admin)return json(origin,{ok:false,error:'admin_denied'},403);await deleteOverride(body.row||{});return json(origin,{ok:true})}const entitlement=admin?{scopes:['premium','report'],plate:String(body?.expected?.plate||'')} : await verifyEntitlement(body.accessToken);if(!entitlement||!entitlement.scopes.includes('report'))return json(origin,{ok:false,error:'paid_access_required'},403);const summaryText=String(body.summaryText||'');const computerText=String(body.computerText||'');if(summaryText.length>250000||computerText.length>250000)return json(origin,{ok:false,error:'text_too_large'},413);if(summaryText.length<5&&!computerText)return json(origin,{ok:false,error:'missing_report_text'},400);const expected=body.expected&&typeof body.expected==='object'?body.expected:{};if(entitlement.plate&&expected.plate&&String(entitlement.plate)!==String(expected.plate).replace(/\D/g,''))return json(origin,{ok:false,error:'vehicle_mismatch'},409);const rows=await overrides();const summary=summaryText?sourceGroundedSummaryResult(applyCustomRules(summaryText,applyServerOverrides(interpretSummaryText(summaryText),rows),rows),summaryText):null;const computer=computerText?applyServerOverrides(interpretComputerText(computerText,expected),rows):null;return json(origin,{ok:true,summary,computer})}catch(error){console.error('BuyTest analyzer error',error);return json(origin,{ok:false,error:error?.message==='invalid_override'?'invalid_override':'analysis_failed'},error?.message==='invalid_override'?400:500)}});

